-- v0.171-v0.175: explicit unresolved conflict sets among claims.
BEGIN;
CREATE TABLE niccolo.situation_analysis_conflict_sets (
 workspace_id UUID NOT NULL,situation_id UUID NOT NULL,analysis_id UUID NOT NULL,conflict_id UUID NOT NULL,
 description TEXT NOT NULL CHECK(length(description) BETWEEN 1 AND 4096 AND btrim(description)<>''),recorded_by_principal_id UUID NOT NULL REFERENCES niccolo_auth.principals(principal_id),created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,situation_id,analysis_id,conflict_id),FOREIGN KEY(workspace_id,situation_id,analysis_id) REFERENCES niccolo.situation_analysis_snapshots(workspace_id,situation_id,analysis_id)
);
CREATE TABLE niccolo.situation_analysis_conflict_claims (
 workspace_id UUID NOT NULL,situation_id UUID NOT NULL,analysis_id UUID NOT NULL,conflict_id UUID NOT NULL,claim_id UUID NOT NULL,
 PRIMARY KEY(workspace_id,situation_id,analysis_id,conflict_id,claim_id),FOREIGN KEY(workspace_id,situation_id,analysis_id,conflict_id) REFERENCES niccolo.situation_analysis_conflict_sets(workspace_id,situation_id,analysis_id,conflict_id),FOREIGN KEY(workspace_id,situation_id,analysis_id,claim_id) REFERENCES niccolo.situation_analysis_claims(workspace_id,situation_id,analysis_id,claim_id)
);
GRANT SELECT,INSERT ON niccolo.situation_analysis_conflict_sets,niccolo.situation_analysis_conflict_claims TO niccolo_app;ALTER TABLE niccolo.situation_analysis_conflict_sets ENABLE ROW LEVEL SECURITY;ALTER TABLE niccolo.situation_analysis_conflict_sets FORCE ROW LEVEL SECURITY;ALTER TABLE niccolo.situation_analysis_conflict_claims ENABLE ROW LEVEL SECURITY;ALTER TABLE niccolo.situation_analysis_conflict_claims FORCE ROW LEVEL SECURITY;
CREATE POLICY workspace_filter ON niccolo.situation_analysis_conflict_sets USING (workspace_id=NULLIF(current_setting('niccolo.workspace_id',true),'')::uuid) WITH CHECK (workspace_id=NULLIF(current_setting('niccolo.workspace_id',true),'')::uuid);CREATE POLICY workspace_filter ON niccolo.situation_analysis_conflict_claims USING (workspace_id=NULLIF(current_setting('niccolo.workspace_id',true),'')::uuid) WITH CHECK (workspace_id=NULLIF(current_setting('niccolo.workspace_id',true),'')::uuid);CREATE POLICY api_read_gate ON niccolo.situation_analysis_conflict_sets AS RESTRICTIVE FOR SELECT TO niccolo_api USING (niccolo_auth.rls_credential_allows(workspace_id,'read'));CREATE POLICY api_write_insert_gate ON niccolo.situation_analysis_conflict_sets AS RESTRICTIVE FOR INSERT TO niccolo_api WITH CHECK (niccolo_auth.rls_credential_allows(workspace_id,'write'));CREATE POLICY api_read_gate ON niccolo.situation_analysis_conflict_claims AS RESTRICTIVE FOR SELECT TO niccolo_api USING (niccolo_auth.rls_credential_allows(workspace_id,'read'));CREATE POLICY api_write_insert_gate ON niccolo.situation_analysis_conflict_claims AS RESTRICTIVE FOR INSERT TO niccolo_api WITH CHECK (niccolo_auth.rls_credential_allows(workspace_id,'write'));
COMMIT;
